const void *dl_builtin_bind_template(const char *name, size_t *size)
{
    if (!strcmp(name, "persist.db")) {
        if (size) *size = sizeof(g_persist_db);
        return g_persist_db;
    }
    if (!strcmp(name, "miwear_record.db")) {
        if (size) *size = sizeof(g_miwear_record_db);
        return g_miwear_record_db;
    }
    if (!strcmp(name, "bt_storage.db")) {
        if (size) *size = sizeof(g_bt_storage_db);
        return g_bt_storage_db;
    }
    if (!strcmp(name, "bt_config.db")) {
        if (size) *size = sizeof(g_bt_config_db);
        return g_bt_config_db;
    }
    return NULL;
}
